import{_ as o,a0 as p,w as s,s as n,I as r,x as e,a1 as i,A as a,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"提高調試能力的一些方法 | LCTT x X-CMD","titleTemplate":false,"description":"提高調試能力的一些方法 | LCTT (202209) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"提高調試能力的一些方法 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"提高調試能力的一些方法 | LCTT (202209) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202209/20220830 Some ways to get better at debugging","title":"提高調試能力的一些方法","tag":"202209","desc":""},"relativePath":"202209/20220830 Some ways to get better at debugging.md","filePath":"[post].md"}'),u={name:"202209/20220830 Some ways to get better at debugging.md"};function g(b,t,m,f,T,x){const l=p("Link");return s(),n("div",null,[t[26]||(t[26]=r("h1",{id:"提高調試能力的一些方法",tabindex:"-1"},[e("提高調試能力的一些方法 "),r("a",{class:"header-anchor",href:"#提高調試能力的一些方法","aria-label":"Permalink to “提高調試能力的一些方法”"},"​")],-1)),t[27]||(t[27]=r("p",null,[r("img",{src:"https://img.linux.net.cn/data/attachment/album/202209/01/222854m78u44otl68yxbyu.jpg",alt:""})],-1)),r("p",null,[t[1]||(t[1]=e("你們好！我一直在編寫一本關於調試的雜誌（這是 ",-1)),i(l,{href:"https://twitter.com/b0rk/status/1562480240240525314?s=20&t=BwKd6i0mVCTaCud2HDEUBA"},{default:a(()=>[...t[0]||(t[0]=[e("目錄的初稿",-1)])]),_:1}),t[2]||(t[2]=e("）。",-1))]),r("p",null,[t[4]||(t[4]=e("作為其中的一部分，我認為閲讀一些關於調試的學術論文可能會很有趣，上週 ",-1)),i(l,{href:"https://third-bit.com/"},{default:a(()=>[...t[3]||(t[3]=[e("Greg Wilson",-1)])]),_:1}),t[5]||(t[5]=e(" 給我發了一些關於調試學術研究的論文。",-1))]),r("p",null,[t[8]||(t[8]=e("其中一篇論文（《",-1)),i(l,{href:"https://dl.acm.org/doi/abs/10.1145/3286960.3286970"},{default:a(()=>[...t[6]||(t[6]=[e("建立一個調試教學的框架[付費牆]",-1)])]),_:1}),t[9]||(t[9]=e("》）對我們有效調試所需的不同種類的知識/技能進行了分類，我非常喜歡。它來自另一篇關於故障排除的更一般性的論文：《",-1)),i(l,{href:"https://www.researchgate.net/profile/Woei-Hung/publication/225547853_Learning_to_Troubleshoot_A_New_Theory-Based_Design_Architecture/links/556f471c08aec226830a74e7/Learning-to-Troubleshoot-A-New-Theory-Based-Design-Architecture.pdf"},{default:a(()=>[...t[7]||(t[7]=[e("學會排錯：一個新的基於理論的設計架構",-1)])]),_:1}),t[10]||(t[10]=e("》。",-1))]),t[28]||(t[28]=d('<p>我認為這個分類對於思考如何更好地進行調試是一個非常有用的結構，所以我把論文中的五個類別重新規劃為你可以採取的行動，以提高調試的效率。</p><p>以下是這些行動：</p><h4 id="_1、學習代碼庫" tabindex="-1">1、學習代碼庫 <a class="header-anchor" href="#_1、學習代碼庫" aria-label="Permalink to “1、學習代碼庫”">​</a></h4><p>要調試一些代碼，你需要了解你正在使用的代碼庫。</p><p>這似乎有點顯而易見（當然，不瞭解代碼的工作原理，你就無法調試代碼！）</p><p>這種學習隨着時間的推移會很自然地發生，而且實際上調試也是 <em>學習</em> 一個新的代碼庫如何工作的最好方法之一—— 看到一些代碼是如何崩潰的，有助於你瞭解它是如何工作的。</p><p>該論文將此稱為“系統知識”。</p><h4 id="_2、學習系統" tabindex="-1">2、學習系統 <a class="header-anchor" href="#_2、學習系統" aria-label="Permalink to “2、學習系統”">​</a></h4><p>論文中提到，你需要了解編程語言，但我認為不止於此 —— 為了修復 bug，往往你需要學習很多更廣泛的環境，而不僅僅是語言。</p><p>舉個例子，如果你是後端 Web 開發者，你可能需要的一些“系統”知識包括：</p><ul><li>HTTP 緩存如何工作</li><li>CORS</li><li>資料庫事務是如何工作的</li></ul><p>我發現我經常需要更有意識地去學習像這樣的系統性的東西 —— 我需要真正花時間去查找和閲讀它們。</p><p>該論文將此稱為“領域知識”。</p><h4 id="_3、學習你的工具" tabindex="-1">3、學習你的工具 <a class="header-anchor" href="#_3、學習你的工具" aria-label="Permalink to “3、學習你的工具”">​</a></h4><p>現在有很多工具，例如：</p><ul><li>調試器（GDB 等）</li><li>瀏覽器開發工具</li><li><ruby>剖析器<rt>profiler</rt></ruby></li><li><code>strace</code> / <code>ltrace</code></li><li><code>tcpdump</code> / <code>wireshark</code></li><li>核心轉儲</li><li>甚至像錯誤信息這樣的基本東西（如何正確閲讀它們）</li></ul><p>我在這個Blog上寫了很多關於調試工具的文章，並且肯定學習這些工具給我帶來了巨大的變化。</p><p>該論文將此稱為“處理性知識”。</p><h4 id="_4、學習策略" tabindex="-1">4、學習策略 <a class="header-anchor" href="#_4、學習策略" aria-label="Permalink to “4、學習策略”">​</a></h4><p>這是最模糊的一類，在如何高效調試的過程中，我們都有很多策略和啓發式方法。比如説：</p><ul><li>寫一個單元測試</li><li>寫一個小的獨立程序來重現這個錯誤</li><li>找到一個能工作的版本的代碼，看看有什麼變化</li><li>打印出無數的東西</li><li>增加額外的日誌記錄</li><li>休息一下</li><li>向朋友解釋這個錯誤，然後在中途發現問題所在</li><li>查看 GitHub 上的問題，看看是否有匹配的問題</li></ul><p>在寫這本雜誌的時候，我一直在思考這個類別，但我想讓這篇文章簡短，所以我不會在這裏多説。</p><p>該論文將此稱為“戰略知識”。</p><h4 id="_5、獲得經驗" tabindex="-1">5、獲得經驗 <a class="header-anchor" href="#_5、獲得經驗" aria-label="Permalink to “5、獲得經驗”">​</a></h4><p>最後一個類別是“經驗”。這篇論文對此有一個非常有趣的評論：</p><blockquote><p>他們的研究結果並沒有顯示出新手和專家所採用的策略有什麼明顯的區別。專家只是形成了更多正確的假設，並且在尋找故障方面更有效率。作者懷疑這個結果是由於新手和專家之間的編程經驗不同造成的。</p></blockquote><p>這真的引起了我的共鳴 —— 我遇到過很多第一次遇到時非常令人沮喪和困難的 bug，而在第五次、第十次或第二十次時就非常簡單了。</p><p>對我來説，這也是最直接的知識類別之一 —— 你需要做的就是調查一百萬個 bug，反正這就是我們作為程序員的全部生活 : ) 。這需要很長的時間，但我覺得它發生得很自然。</p><p>本文將此稱為“經驗知識”。</p><h4 id="就這樣吧" tabindex="-1">就這樣吧！ <a class="header-anchor" href="#就這樣吧" aria-label="Permalink to “就這樣吧！”">​</a></h4><p>我打算把這篇文章寫得很短，我只是非常喜歡這個分類，想把它分享出來。</p><hr>',32)),r("p",null,[t[12]||(t[12]=e("via: ",-1)),i(l,{href:"https://jvns.ca/blog/2022/08/30/a-way-to-categorize-debugging-skills/"},{default:a(()=>[...t[11]||(t[11]=[e("https://jvns.ca/blog/2022/08/30/a-way-to-categorize-debugging-skills/",-1)])]),_:1})]),r("p",null,[t[17]||(t[17]=e("作者：",-1)),i(l,{href:"https://jvns.ca/"},{default:a(()=>[...t[13]||(t[13]=[e("Julia Evans",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),i(l,{href:"https://github.com/lkxed"},{default:a(()=>[...t[14]||(t[14]=[e("lkxed",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),i(l,{href:"https://github.com/aftermath0703"},{default:a(()=>[...t[15]||(t[15]=[e("aftermath0703",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:a(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const w=o(u,[["render",g]]);export{C as __pageData,w as default};
